/* ---------- helpers ---------- */
function fmt(s,o){ return s.replace(/\{(\w+)\}/g,function(m,k){ return o[k]!==undefined?o[k]:m; }); }
function esc(s){ return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); }
function attr(s){ return esc(s).replace(/'/g,"&#39;"); }
function byId(list,id){ for (var i=0;i<list.length;i++) if (list[i].id===id) return list[i]; return null; }
function task(id){ return byId(TASKS,id); } function project(id){ return byId(PROJECTS,id); } function asset(id){ return byId(ASSETS,id); } function page(id){ return byId(KNOWLEDGE,id); } function request(id){ return byId(REQUESTS,id); }
function team(id){ return byId(TEAMS,id)||null; } function teamName(id){ var t=team(id); return t?t.name:"No team"; } function teamVar(id){ var t=team(id); if (!t) return "var(--team-gray)"; return /^#/.test(t.color)?t.color:"var(--team-"+t.color+")"; }
function teamColorCss(c){ return /^#/.test(c||"")?c:"var(--team-"+(c||"gray")+")"; }
function teamBadge(id,cls){ var t=team(id); if (!t) return '<span class="tbadge'+(cls?" "+cls:"")+'" style="--tc:var(--team-gray)"><i></i>'+tr("No team")+'</span>'; return '<span class="tbadge'+(cls?" "+cls:"")+'" style="--tc:'+teamVar(id)+'"><i></i>'+esc(t.name)+'</span>'; }
function requestBadge(t){ return isRequestTask(t)?'<span class="badge req" title="Submitted as a creative request by '+attr(person(t.createdBy).name)+'">request</span>':""; }
function teamIcon(t,sm){ var ic=t.icon||"palette"; var inner=/^data:image\/svg\+xml/.test(ic)?'<img src="'+ic+'" alt="">':(TICONS[ic]||TICONS.palette); return '<span class="ticon'+(sm?" sm":"")+(t.iconRaw?" raw":"")+'" style="--tc:'+teamColorCss(t.color)+'">'+inner+'</span>'; }
function teamsOf(id){ var p=person(id); return (p.teams||[]).map(function(x){ return x[0]; }); } function primaryTeam(id){ var p=person(id); var t=(p.teams||[]).filter(function(x){ return x[1]; })[0]||(p.teams||[])[0]; return t?t[0]:null; }
function teamMembers(tid){ return Object.keys(PEOPLE).filter(function(id){ return teamsOf(id).indexOf(tid)>=0; }); }
function activeTeams(){ return TEAMS.filter(function(t){ return !t.archived; }).sort(function(a,b){ return a.sort-b.sort; }); }
function stage(id){ var st=WS.workflow||[]; for (var i=0;i<st.length;i++) if (st[i].id===id) return st[i]; return {id:id,kind:"",name:id}; }
function stageName(id){ return stage(id).name; } function stageKind(id){ return stage(id).kind; }
function isClosed(tk){ return stageKind(tk.status)==="closed"; } function isReview(tk){ return stageKind(tk.status)==="review"; }
function isSuccessfulTask(tk){ return !!tk&&stageKind(tk.status)==="closed"&&tk.status!=="declined"; }
function projectProgressInfo(p,taskRows){
  var rows=(taskRows||TASKS).filter(function(t){ return t&&t.proj===p.id&&!t._draft&&!t.tutorial&&t.status!=="declined"; });
  var taskEffort=rows.reduce(function(n,t){ return n+Math.max(0,+t.effort||0); },0);
  var doneEffort=rows.reduce(function(n,t){ return n+(isSuccessfulTask(t)?Math.max(0,+t.effort||0):0); },0);
  var taskDone=rows.filter(isSuccessfulTask).length;
  var taskPct=rows.length?(taskEffort>0?Math.round(doneEffort/taskEffort*100):Math.round(taskDone/rows.length*100)):null;
  var milestones=p.milestones||[], milestoneDone=milestones.filter(function(m){ return m.done; }).length;
  var milestonePct=milestones.length?Math.round(milestoneDone/milestones.length*100):null;
  var value=taskPct!=null&&milestonePct!=null?Math.round(taskPct*.6+milestonePct*.4):taskPct!=null?taskPct:milestonePct!=null?milestonePct:(p.status==="done"||p.status==="archived"?100:0);
  return {value:value,taskPct:taskPct,milestonePct:milestonePct,taskDone:taskDone,taskTotal:rows.length,doneEffort:doneEffort,totalEffort:taskEffort,milestoneDone:milestoneDone,milestoneTotal:milestones.length};
}
function projectProgress(p,taskRows){ return projectProgressInfo(p,taskRows).value; }
function person(id){ return PEOPLE[id]||{name:id||"Unassigned",ini:id?"?":"–",c:4,role:"",cap:40,teams:[]}; } function first(id){ return person(id).name.split(" ")[0]; }
function assigneesOf(t){ var a=(t.assignees||[]).slice(); if (t.assignee&&a.indexOf(t.assignee)<0) a.unshift(t.assignee); return a.filter(function(x){ return !!x; }); }
function reviewersOf(t){ var a=(t.reviewers||[]).slice(); if (t.reviewer&&a.indexOf(t.reviewer)<0) a.unshift(t.reviewer); return a.filter(function(x){ return !!x; }); }
function isAssignee(t,id){ return assigneesOf(t).indexOf(id)>=0; } function isReviewer(t,id){ return reviewersOf(t).indexOf(id)>=0; } function involved(t,id){ return isAssignee(t,id)||isReviewer(t,id)||t.createdBy===id; }
function avStack(ids,max){ ids=ids||[]; max=max||3; return '<span class="av-stack">'+ids.slice(0,max).map(function(id){ return av(id); }).join("")+(ids.length>max?'<span class="av" style="background:var(--color-border-strong);color:var(--color-text-primary)">+'+(ids.length-max)+'</span>':"")+'</span>'; }
function av(id,cls){ var p=person(id); if (p.avatar) return '<span class="av img'+(cls?' '+cls:'')+'" style="background-image:url(&quot;'+attr(p.avatar)+'&quot;)" title="'+attr(p.name)+'"></span>'; return '<span class="av c'+p.c+(cls?' '+cls:'')+'" title="'+attr(p.name)+'">'+p.ini+'</span>'; }
function ago(m){ if (UI_LANG==="id"){ if(m<1)return "baru saja"; if(m<60)return Math.round(m)+" mnt lalu"; if(m<1440)return Math.round(m/60)+" jam lalu"; return Math.round(m/1440)+" hari lalu"; } if (m<1) return "just now"; if (m<60) return Math.round(m)+"m ago"; if (m<1440) return Math.round(m/60)+"h ago"; return Math.round(m/1440)+"d ago"; }
function dueTxt(d){ if(UI_LANG==="id"){ if(d<0)return (-d)+" hari terlambat"; if(d===0)return "hari ini"; if(d===1)return "besok"; return d+" hari lagi"; } if (d<0) return (-d)+"d overdue"; if (d===0) return "today"; if (d===1) return "tomorrow"; return "in "+d+"d"; }
function dueCls(d,tk){ if (tk&&isClosed(tk)) return ""; if (d<0) return "over"; if (d===0) return "today"; return ""; }
var MO=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"], MOL=["January","February","March","April","May","June","July","August","September","October","November","December"], DOW=["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"], MO_ID=["Jan","Feb","Mar","Apr","Mei","Jun","Jul","Agu","Sep","Okt","Nov","Des"], MOL_ID=["Januari","Februari","Maret","April","Mei","Juni","Juli","Agustus","September","Oktober","November","Desember"], DOW_ID=["Minggu","Senin","Selasa","Rabu","Kamis","Jumat","Sabtu"];
function uiMo(i){ return UI_LANG==="id"?MO_ID[i]:MO[i]; } function uiMol(i){ return UI_LANG==="id"?MOL_ID[i]:MOL[i]; } function uiDow(i){ return UI_LANG==="id"?DOW_ID[i]:DOW[i]; }
function dateOf(d){ var x=new Date(TODAY); x.setDate(x.getDate()+d); return x; }
function dueDate(d){ var x=dateOf(d); return uiMo(x.getMonth())+" "+x.getDate(); }
function iso(d){ var x=dateOf(d); return x.getFullYear()+"-"+String(x.getMonth()+1).padStart(2,"0")+"-"+String(x.getDate()).padStart(2,"0"); }
function offsetFromIso(s){ if (!s) return 0; var p=String(s).slice(0,10).split("-"); var x=new Date(+p[0],+p[1]-1,+p[2]); return Math.round((x-TODAY)/86400000); }
function minAgo(isoT){ if (!isoT) return 0; return Math.max(0,(Date.now()-new Date(isoT).getTime())/60000); } function isoAgo(m){ return new Date(Date.now()-(m||0)*60000).toISOString(); }
function prioL(p){ p=p||"medium"; return tr(p.charAt(0).toUpperCase()+p.slice(1)); }
function badgeCls(status){ var k=stageKind(status); return k==="review"?"review":k==="closed"?"approved":k==="revision"?"revision":k==="work"?"prog":""; }
function statusBadge(status){ return '<span class="badge status '+badgeCls(status)+'">'+esc(tr(stageName(status)))+'</span>'; }
function boardTasks(){ return TASKS.filter(function(x){ return !projArchived(x.proj); }); }
function openTasks(){ return boardTasks().filter(function(x){ return !isClosed(x); }); }
/* ---------- task dependencies: Finish → Start, derived not manually set ---------- */
function dependenciesOf(tk){ return ((tk&&tk.dependencies)||[]).map(function(d){ return task(d.taskId); }).filter(Boolean); }
function blockingTasksOf(tk){ return TASKS.filter(function(x){ return ((x.dependencies)||[]).some(function(d){ return d.taskId===tk.id; }); }); }
function unresolvedDependencies(tk){ return dependenciesOf(tk).filter(function(x){ return !isClosed(x); }); }
function isTaskBlocked(tk){ return !isClosed(tk)&&unresolvedDependencies(tk).length>0; }
function dependencyState(tk){ return isClosed(tk)?"completed":(isTaskBlocked(tk)?"blocked":"ready"); }
function dependencyCount(tk){ return unresolvedDependencies(tk).length; }
function wouldCreateDependency(tk, depId){ var start=task(depId), seen={}; function reaches(cur){ if(!cur||seen[cur.id]) return false; if(cur.id===tk.id) return true; seen[cur.id]=true; return dependenciesOf(cur).some(reaches); } return !!start&&reaches(start); }
function dependencyBadge(tk,compact){ var n=dependencyCount(tk), all=(tk.dependencies||[]).length; if(isClosed(tk)) return compact?'':'<span class="badge approved" title="Completed">'+I.check+'Completed</span>'; if(n){ var names=unresolvedDependencies(tk).map(function(x){return x.title+" — "+stageName(x.status);}).join("\n"); return '<span class="badge revision" title="Blocked by '+attr(names)+'">⛓ '+(compact?n:"Blocked · "+n)+'</span>'; } if(all) return '<span class="badge approved" title="All dependencies are complete">'+I.check+(compact?"":"Ready")+'</span>'; return ""; }
function dependencyRisk(tk){ return unresolvedDependencies(tk).filter(function(dep){ return tk.due!=null&&dep.due!=null&&dep.due>tk.due; }); }
function sortTasks(a){ return a.slice().sort(function(x,y){ return (x.due-y.due)||(PRANK[x.prio]-PRANK[y.prio]); }); }
function projName(tk){ var p=project(tk.proj); return p?p.name:"—"; }
function isRequestTask(t){ var s=WS.workflow[0]; return !!t&&((t.tags||[]).indexOf("request")>=0||(!t.assignee&&s&&t.status===s.id)); }
function firstStage(){ return (WS.workflow[0]||{}).id; }
function projArchived(pid){ var p=project(pid); return !!(p&&p.status==="archived"); }
function liveProjects(){ return PROJECTS.filter(function(p){ return p.status!=="archived"; }); }
/* ---------- labels: a coloured, workspace-defined marker on a task ---------- */
var LABEL_COLORS=[["blue","#1F4FD8"],["navy","#0B2A5B"],["green","#16A34A"],["lime","#84CC16"],["amber","#D97706"],["red","#DC2626"],["pink","#DB2777"],["purple","#7C3AED"],["teal","#0F766E"],["slate","#475569"]];
var LABELS_DEFAULT=[
  {id:"lb_gd",  name:"Graphic Designer", color:"#1F4FD8"},
  {id:"lb_ve",  name:"Video Editor",     color:"#7C3AED"},
  {id:"lb_mo",  name:"Motion",           color:"#D97706"},
  {id:"lb_cw",  name:"Copywriter",       color:"#DB2777"},
  {id:"lb_ui",  name:"UI/UX",            color:"#0F766E"},
  {id:"lb_ph",  name:"Photographer",     color:"#16A34A"},
  {id:"lb_cm",  name:"Compliance",       color:"#DC2626"}
];
function allLabels(){ var l=(WS&&WS.labels); return (l&&l.length)?l:LABELS_DEFAULT; }
function label(id){ var l=allLabels(); for (var i=0;i<l.length;i++) if (l[i].id===id) return l[i]; return null; }
function labelsOf(t){ return ((t&&t.labels)||[]).map(label).filter(Boolean); }
function labelChip(l,click){ return '<span class="lbl" style="--lc:'+attr(l.color)+'"'+(click?' onclick="event.stopPropagation();filterByLabel(\''+l.id+'\')" title="Filter by '+attr(l.name)+'"':'')+'>'+esc(l.name)+'</span>'; }
function labelChips(t,click){ var ls=labelsOf(t); if (!ls.length) return ""; return '<span class="lbls">'+ls.map(function(l){ return labelChip(l,click); }).join("")+'</span>'; }
function labelPills(t){
  var ls=labelsOf(t); if (!ls.length) return "";
  return '<span class="lbl-pills" onclick="event.stopPropagation();toggleChipLabels()" title="'+attr(ls.map(function(l){ return l.name; }).join(", "))+' \u00b7 click to name every label">'
    + ls.slice(0,4).map(function(l){ return '<i style="background:'+attr(l.color)+'"></i>'; }).join("") + '</span>';
}
function labelFull(t){
  var ls=labelsOf(t); if (!ls.length) return "";
  /* names only \u2014 clicking collapses the row again rather than filtering */
  return '<span class="lbl-full" onclick="event.stopPropagation();toggleChipLabels()" title="Click to collapse">'
    + ls.map(function(l){ return labelChip(l,false); }).join("") + '</span>';
}
/* one switch for the whole calendar, not per card */
function toggleChipLabels(on){
  S.calLabelsOpen = on===undefined ? !S.calLabelsOpen : !!on;
  renderScreen(false);
}
function filterByLabel(id){ if(typeof useManualTaskFilters==="function")useManualTaskFilters(); S.filters.label=(S.filters.label===id?"":id); S.taskScope="all"; go("tasks", S.taskView||"kanban"); }
function openDashboardTaskFilter(kind,value){
  /* Home KPIs are a temporary lens. Preserve any filter the user set manually. */
  S._manualTaskFilters=clone(S.filters||{}); S._manualTaskScope=S.taskScope; S._manualActiveView=S.activeView;
  S.filters={status:"",kind:"",assignee:"",reviewer:"",proj:"",prio:"",team:"",tag:"",dependency:"",due:"",archived:"",hidden:"",label:"",dueFrom:"",dueTo:""};
  if(kind==="overdue") S.filters.due="overdue";
  if(kind==="delivered") S.filters.kind="closed";
  if(kind==="autohidden") S.filters.hidden="only";
  if(kind==="stage") S.filters.status=value||"";
  if(kind==="inbox") S.filters.status=firstStage();
  S._temporaryTaskFilter=true;
  S.taskScope="all"; S.activeView=null; go("tasks","list");
}
function emptyTaskFilters(){ return {status:"",kind:"",assignee:"",reviewer:"",proj:"",prio:"",team:"",tag:"",dependency:"",due:"",archived:"",hidden:"",label:"",dueFrom:"",dueTo:""}; }
function openHomeTasks(filters,scope){
  S._manualTaskFilters=clone(S._lastManualTaskFilters||S.filters||emptyTaskFilters());S._manualTaskScope=S._lastManualTaskScope||S.taskScope;S._manualActiveView=S._lastManualActiveView||S.activeView;
  S.filters=Object.assign(emptyTaskFilters(),filters||{});S.taskScope=scope||"all";S.activeView=null;S._temporaryTaskFilter=true;go("tasks","list");
}
function visibleBoardTasks(){return boardTasks().filter(function(t){return !t.hidden&&!autoHidden(t)&&!t._draft;});}
function homeKpiKind(previous){ var f=S.filters||{},p=previous||{}; if(f.due==="overdue"&&f.due!==p.due)return "overdue"; if(f.kind==="closed"&&f.kind!==p.kind)return "delivered"; if((f.hidden==="show"||f.hidden==="only")&&f.hidden!==p.hidden)return "autohidden"; if(f.status===firstStage()&&f.status!==p.status)return "inbox"; return ""; }

/* ---------- task fields: every field is configurable, not just the extra ones ---------- */
var TASK_FIELDS_DEFAULT=[
  /* Header-owned values default to hidden below the approved header. Admins
     can still expose them without changing the task model. */
  {id:"status",     name:"Status",       builtin:true, displayMode:"hidden"},
  {id:"prio",       name:"Priority",     builtin:true, displayMode:"primary"},
  {id:"team",       name:"Team",         builtin:true, displayMode:"primary"},
  {id:"assignees",  name:"Assignees",    builtin:true, displayMode:"primary"},
  {id:"reviewers",  name:"Reviewers",    builtin:true, displayMode:"primary"},
  {id:"due",        name:"Due",          builtin:true, displayMode:"primary"},
  {id:"proj",       name:"Project",      builtin:true, displayMode:"primary"},
  {id:"labels",     name:"Labels",       builtin:true, displayMode:"primary"},
  {id:"tags",       name:"Tags",         builtin:true, displayMode:"primary"},
  {id:"start",      name:"Start",        builtin:true, displayMode:"secondary"},
  {id:"effort",     name:"Estimate",     builtin:true, displayMode:"secondary"},
  /* This remains the existing manual expected-output value; the clearer label
     avoids confusing it with attached files/versions. */
  {id:"assetCount", name:"Deliverables", builtin:true, displayMode:"secondary"}
];
function taskFieldMode(f,d){ var m=f&&f.displayMode; if(["primary","secondary","hidden"].indexOf(m)>=0) return m; if(f&&f.show===false) return "hidden"; return (d&&d.displayMode)||"primary"; }
/* stored config is merged over the defaults so a new built-in never disappears */
function taskFields(){
  var saved=(WS&&WS.taskFields)||[];
  var byId={}; saved.forEach(function(f){ byId[f.id]=f; });
  var out=[], seen={};
  saved.forEach(function(f){ var d=null; TASK_FIELDS_DEFAULT.forEach(function(x){ if (x.id===f.id) d=x; }); if (!d) return; var mode=taskFieldMode(f,d); seen[f.id]=1; out.push({id:d.id,name:f.name||d.name,builtin:true,displayMode:mode,show:mode!=="hidden"}); });
  TASK_FIELDS_DEFAULT.forEach(function(d){ if (!seen[d.id]){ var f=byId[d.id]||{}, mode=taskFieldMode(f,d); out.push({id:d.id,name:f.name||d.name,builtin:true,displayMode:mode,show:mode!=="hidden"}); } });
  return out;
}
function fieldLabel(id){ var f=taskFields(); for (var i=0;i<f.length;i++) if (f[i].id===id) return f[i].name; return id; }

/* ---------- deliverable assets: count per task + the links attached to it ---------- */
function assetCount(t){ return Math.max(0,+((t&&t.assetCount)||0)); }
function assetsProduced(list){ var n=0; (list||[]).forEach(function(t){ n+=assetCount(t); }); return n; }
function isLink(u){ return !!u&&/^(https?:|s3:|gs:|ftp:)/i.test(String(u)); }
/* every external link that hangs off a task: approved/latest versions first, then files */
function taskAssetLinks(t){ var out=[]; if (!t) return out;
  (t.versions||[]).forEach(function(v){ var u=v.driveUrl||v.url; if (isLink(u)) out.push({url:u,name:"Version "+v.n+(v.note?" \u2014 "+v.note:""),kind:"version",v:v.n,state:v.state,ago:v.ago,by:v.by,task:t}); });
  (t.files||[]).forEach(function(f){ if (isLink(f.url)) out.push({url:f.url,name:f.name,kind:"file",src:f.source,size:f.size,ago:f.ago,task:t}); });
  out.sort(function(a,b){ return (a.ago||0)-(b.ago||0); }); return out; }
function assetLinks(list){ var out=[]; (list||[]).forEach(function(t){ out=out.concat(taskAssetLinks(t)); }); return out; }
/* the one link people actually want: the approved version, else the newest link on the task */
function finalAssetLink(t){ var ls=taskAssetLinks(t); if (!ls.length) return null; var ap=ls.filter(function(l){ return l.kind==="version"&&l.state==="approved"; }); if (ap.length) return ap.sort(function(a,b){ return b.v-a.v; })[0]; var vs=ls.filter(function(l){ return l.kind==="version"; }); if (vs.length) return vs.sort(function(a,b){ return b.v-a.v; })[0]; return ls[0]; }
function assetBadge(t){ var n=assetCount(t); return '<span class="acount'+(n?"":" zero")+'" title="Assets produced for this task">'+I.assets.replace('class="i"','style="width:11px;height:11px;stroke:currentColor;fill:none;stroke-width:2"')+n+'</span>'; }

/* ---------- auto-hide / auto-archive (Settings → Automation) ---------- */
var AUTOHIDE_DEFAULT={tasks:"month",taskDays:30,projects:"month",projectDays:30};
function autoHideCfg(){ var a=(WS&&WS.autoHide)||{}; return {tasks:a.tasks||AUTOHIDE_DEFAULT.tasks,taskDays:+a.taskDays||AUTOHIDE_DEFAULT.taskDays,projects:a.projects||AUTOHIDE_DEFAULT.projects,projectDays:+a.projectDays||AUTOHIDE_DEFAULT.projectDays}; }
function autoCutoff(mode,days){ if (mode==="month"){ var m=new Date(); m.setDate(1); m.setHours(0,0,0,0); return m; } if (mode==="quarter"){ var q=new Date(); q.setMonth(Math.floor(q.getMonth()/3)*3,1); q.setHours(0,0,0,0); return q; } return new Date(Date.now()-Math.max(1,days)*86400000); }
function closedAt(t){ if(t.completedAt)return new Date(t.completedAt);var events=(t.activity||[]).filter(function(x){return x.k==="approved"||(x.k==="moved"&&x.a&&stageKind(x.a.to)==="closed");}).map(function(x){return new Date(x.createdAt||isoAgo(x.ago||0));}).sort(function(a,b){return b-a;});return events[0]||dateOf(t.due); }
function autoHidden(t){ var c=autoHideCfg(); if (c.tasks==="off"||!t||!isClosed(t)) return false; return closedAt(t)<autoCutoff(c.tasks,c.taskDays); }
function autoHiddenCount(){ return TASKS.filter(function(t){ return !t.hidden&&autoHidden(t); }).length; }
function autoHideLabel(){ var c=autoHideCfg(); return c.tasks==="off"?"off":c.tasks==="month"?"previous months":c.tasks==="quarter"?"previous quarters":"older than "+c.taskDays+" days"; }
function sweepArchiveLocal(){ var c=autoHideCfg(); if (c.projects==="off") return 0; var m=autoCutoff(c.projects,c.projectDays); var n=0; PROJECTS.forEach(function(p){ if (p.status==="done"&&p.completedAt&&new Date(p.completedAt)<m){ p.status="archived"; p.archivedAt=new Date().toISOString(); n++; } }); return n; }
function assigned(id){ var h=0; TASKS.forEach(function(x){ if (isClosed(x)||projArchived(x.proj)) return; var a=assigneesOf(x); if (a.indexOf(id)>=0) h+=x.effort/a.length; }); return Math.round(h); }
function nextId(prefix,list){ var m=100; list.forEach(function(x){ var n=parseInt(String(x.id).replace(/\D/g,""),10); if (n>m) m=n; }); return prefix+(m+1); }
function uid(p){ return (p||"id")+"_"+Date.now().toString(36)+Math.random().toString(36).slice(2,7); }
function A(who,k,agoMin,a){ return {id:uid("act"),who:who,k:k,ago:agoMin||0,a:a||{}}; }
function log(tk,k,a){ tk.activity.push(A(ME,k,0,a)); var o={task:tk.id}; if (a) for (var q in a) o[q]=a[q]; ACTIVITY.unshift(A(ME,k,0,o)); }
function download(name, blob){ var a=document.createElement("a"); a.href=URL.createObjectURL(blob); a.download=name; document.body.appendChild(a); a.click(); setTimeout(function(){ URL.revokeObjectURL(a.href); a.remove(); },500); }
function clone(o){ return JSON.parse(JSON.stringify(o)); }
function replaceInto(target,src){ for (var k in target) if (Object.prototype.hasOwnProperty.call(target,k)) delete target[k]; for (var j in src) target[j]=src[j]; return target; }

/* ---------- permissions (mirror of server/permissions.js — the server is authoritative) ---------- */
var RANK={viewer:0,member:1,team_lead:2,creative_lead:3,admin:4};
function role(){ return person(ME).perm||"member"; }
function has(cap){ var r=role(); if (r==="admin") return true; var ro=byId(ROLES,r); return !!(ro&&(ro.permissions||[]).indexOf(cap)>=0); }
function leadsTeam(tid){ var t=team(tid); return !!(t&&t.lead===ME); }
function teamScoped(t){ return has("edit_team_tasks")&&(leadsTeam(t.team)||teamsOf(ME).indexOf(t.team)>=0); }
var canI={ submitRequest:function(){ return has("submit_request")||has("create_task"); }, manageWorkspace:function(){ return has("manage_workspace"); }, manageTeams:function(){ return has("manage_teams"); }, manageMembers:function(){ return has("manage_members"); }, manageRoles:function(){ return has("manage_roles"); }, createProject:function(){ return has("create_project"); },
  createTask:function(){ return has("create_task")||has("create_own_task"); }, editTask:function(t){ return has("edit_any_task")||teamScoped(t)||(has("edit_own_task")&&(isAssignee(t,ME)||isReviewer(t,ME))); },
  assignTask:function(t){ return has("assign_task")||(has("edit_team_tasks")&&leadsTeam(t.team)); }, reviewTask:function(t){ return has("review_any")||isReviewer(t,ME)||(has("edit_team_tasks")&&leadsTeam(t.team)); }, deleteTask:function(){ return has("delete_task"); },
  decideRequest:function(){ return has("decide_request"); }, manageAssets:function(){ return has("manage_assets"); }, manageKnowledge:function(){ return has("manage_knowledge"); }, viewAnalytics:function(){ return has("view_analytics"); } };

/* ---------- API + hydration (wire docs use ISO dates; the UI works in day offsets / minutes ago) ---------- */
var SESSION={user:null,ws:null,canRegister:true};
function httpStatusMessage(st){ return st===502||st===503?tr("The server could not be reached (")+st+tr("). It may be restarting — try again in a minute."):st===504||st===524?tr("The request took too long (")+st+tr("). Try again; for AI, pick a faster model or a smaller size."):st===413?tr("That upload is too large."):tr("Unexpected server response (HTTP ")+st+")."; }
function apiFetch(method,path,body){ var h={"Content-Type":"application/json"}; if (SESSION.user&&ME!==SESSION.user.id) h["x-act-as"]=ME; return fetch(API.base+path,{method:method,credentials:"same-origin",headers:h,body:body!==undefined?JSON.stringify(body):undefined}).then(function(r){ return r.text().then(function(t){ var j; try { j=t?JSON.parse(t):{}; } catch(e){ /* v38: a proxy/CDN error page (HTML) is never shown raw */ j={error:/^\s*</.test(t)?httpStatusMessage(r.status):String(t).slice(0,300)}; } if (r.status===401&&path.indexOf("/api/auth/")<0){ showLogin(j.error||"Please sign in"); } if (!r.ok) throw new Error(j.error||("HTTP "+r.status)); return j; }); }); }
function hTask(d){ var t=clone(d); t.due=offsetFromIso(d.dueDate); t.span=Math.max(1,t.due-offsetFromIso(d.startDate||d.dueDate)); t.ago=minAgo(d.createdAt); t.prio=t.prio==="normal"?"medium":(t.prio||"medium"); t.tags=t.tags||[]; t.dependencies=Array.isArray(d.dependencies)?d.dependencies:[]; t.assignees=assigneesOf(t); t.reviewers=reviewersOf(t); t.hidden=!!t.hidden; t.assetCount=Math.max(0,+(d.assetCount||0)); t.labels=Array.isArray(d.labels)?d.labels.slice():[]; t.custom=t.custom||{}; t.description=t.description||"";
  t.versions=(d.versions||[]).map(function(v){ var x=clone(v); x.ago=minAgo(v.createdAt); x.decidedAgo=v.decidedAt?minAgo(v.decidedAt):null; return x; }); t.files=(d.files||[]).map(function(f){ var x=clone(f); x.ago=minAgo(f.createdAt); return x; }); t.comments=(d.comments||[]).map(function(c){ var x=clone(c); x.ago=minAgo(c.createdAt); x.attachments=x.attachments||[]; return x; }); t.activity=(d.activity||[]).map(function(a){ var x=clone(a); x.ago=minAgo(a.createdAt); return x; }); return t; }
function dTask(t){ var d=clone(t); d.dueDate=iso(t.due); d.startDate=iso(t.due-(t.span||1)); d.createdAt=t.createdAt||isoAgo(t.ago); delete d.due; delete d.span; delete d.ago;
  d.versions=t.versions.map(function(v){ var x=clone(v); x.id=x.id||uid("ver"); x.createdAt=v.createdAt||isoAgo(v.ago); x.decidedAt=v.decidedAt||(v.decidedAgo!=null?isoAgo(v.decidedAgo):null); delete x.ago; delete x.decidedAgo; return x; }); d.files=t.files.map(function(f){ var x=clone(f); x.id=x.id||uid("file"); x.createdAt=f.createdAt||isoAgo(f.ago); delete x.ago; return x; });
  d.comments=t.comments.map(function(c){ var x=clone(c); x.id=x.id||uid("cm"); x.createdAt=c.createdAt||isoAgo(c.ago); delete x.ago; return x; }); d.activity=t.activity.map(function(a){ var x=clone(a); x.id=x.id||uid("act"); x.createdAt=a.createdAt||isoAgo(a.ago); delete x.ago; return x; }); return d; }
function hProject(d){ var p=clone(d); p.start=offsetFromIso(d.startDate); p.due=offsetFromIso(d.dueDate); p.milestones=(d.milestones||[]).map(function(m){ return {id:m.id,name:m.name,due:offsetFromIso(m.dueDate),done:!!m.done}; }); p.teams=p.teams||[]; p.team=p.team||[]; p.tags=p.tags||[]; return p; }
