document.addEventListener("click",function(e){ if (e.target&&e.target.isConnected===false) return; if (!e.target.closest(".pop") && !e.target.closest(".menu") && !e.target.closest(".iconbtn") && !e.target.closest("[data-menu]") && !e.target.closest("#meBtn")) closePops(); });
document.addEventListener("keydown",function(e){ if (e.key==="Escape"){ if (document.getElementById("modalWrap").classList.contains("open")){ closePops(); closeModal(); } else if (typeof AI_CHAT!=="undefined"&&AI_CHAT.open){ closePops(); aiChatToggle(false); } else { closePops(); closeDrawer(); } } if ((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==="k"){ e.preventDefault(); if(window.innerWidth<=980)toggleSearchBar(true); else document.getElementById("searchInput").focus(); } });
function openModal(title,body,foot,lg){ var m=document.getElementById("modal"); m.className="modal"+(lg?" lg":""); m.innerHTML='<div class="modal-head"><h3>'+tr(title)+'</h3><span class="spacer"></span><button class="iconbtn" onclick="closeModal()" aria-label="'+attr(tr("Close"))+'">'+I.x+'</button></div><div class="modal-body">'+body+'</div>'+(foot?'<div class="modal-foot">'+foot+'</div>':''); localizeVisibleText(m); document.getElementById("modalWrap").classList.add("open"); var f=m.querySelector("input,textarea,select"); if (f) setTimeout(function(){ f.focus(); },50); }
function closeModal(){ document.getElementById("modalWrap").classList.remove("open"); }
function confirmModal(title,text,onok,danger){ window._confirmCb=onok; openModal(title,'<p>'+text+'</p>','<button class="btn" onclick="closeModal()">'+tr("Cancel")+'</button><button class="btn '+(danger?"danger":"primary")+'" onclick="closeModal();window._confirmCb()">'+tr(danger?"Delete":"Confirm")+'</button>'); }
function val(id){ var el=document.getElementById(id); return el?el.value.trim():""; }
function require(ids){ var ok=true; ids.forEach(function(id){ var el=document.getElementById(id); if (!el) return; var f=el.closest(".field"); var bad=!el.value.trim(); if (f) f.classList.toggle("invalid",bad); if (bad) ok=false; }); return ok; }
function fieldHtml(id,label,inner,err){ return '<div class="field" id="f_'+id+'"><label for="'+id+'">'+tr(label)+'</label>'+inner+'<div class="err">'+tr(err||"Required")+'</div></div>'; }
function selectHtml(id,opts,cur,extra){ return '<select id="'+id+'" '+(extra||"")+'>'+opts.map(function(o){ var v=typeof o==="string"?o:o[0]; var l=typeof o==="string"?o:o[1]; return '<option value="'+attr(v)+'"'+(v===cur?" selected":"")+'>'+esc(l)+'</option>'; }).join("")+'</select>'; }
function peopleOpts(){ return Object.keys(PEOPLE).filter(function(k){ return !PEOPLE[k].stakeholder; }).map(function(k){ return [k,PEOPLE[k].name]; }); }
function teamOpts(withNone){ return (withNone?[["","No team"]]:[]).concat(activeTeams().map(function(t){ return [t.id,t.name]; })); }

