function myPrefs(){ var p=PEOPLE[ME]; if (!p) return {}; p.prefs=p.prefs||{}; if (!p.prefs._loaded){ try { var l=JSON.parse(localStorage.getItem("cos.prefs."+ME)||"null"); if (l) for (var k in l) if (p.prefs[k]===undefined) p.prefs[k]=l[k]; } catch(e){} p.prefs._loaded=true; } return p.prefs; }
function saveMyPrefs(){ var p=PEOPLE[ME]; if (!p) return; var c=clone(p.prefs||{}); delete c._loaded; try { localStorage.setItem("cos.prefs."+ME,JSON.stringify(c)); } catch(e){} if (API.on){ var body=clone(p); body.prefs=c; apiFetch("PUT","/api/members/"+ME+"?prefsOnly=1",Object.assign({id:ME},body)).catch(function(){}); } }
function detectedShortcutStyle(){var platform="";try{platform=(navigator.userAgentData&&navigator.userAgentData.platform)||navigator.platform||navigator.userAgent||"";}catch(e){}return /Mac|iPhone|iPad|iPod/i.test(platform)?"mac":"ctrl";}
function shortcutStyle(){var pref=(myPrefs().shortcutStyle||"auto");return pref==="mac"?"mac":pref==="ctrl"?"ctrl":detectedShortcutStyle();}
function shortcutModifier(){return shortcutStyle()==="mac"?"⌘":"Ctrl";}
function shortcutCombo(key){return shortcutModifier()+(shortcutStyle()==="mac"?" ":" + ")+key;}
function syncShortcutHints(){var el=document.getElementById("searchShortcut");if(el)el.textContent=shortcutModifier()+" K";}
function setShortcutStyle(value){var p=myPrefs();p.shortcutStyle=["auto","ctrl","mac"].indexOf(value)>=0?value:"auto";saveMyPrefs();syncShortcutHints();if(S.drawerTask)renderDrawer();if(S.screen==="settings")renderScreen(false);toast(tr("Shortcut display updated"));}

