/* v39 Indonesian UI uses the loanword "Task" (not "tugas") everywhere — normalised at every exit point */
function idTerms(s){ return typeof s==="string"?s.replace(/\b([Tt])ugas\b/g,function(_,c){ return c==="T"?"Task":"task"; }):s; }
function tr(s){ return UI_LANG==="id" ? idTerms(UI_ID[s]||s) : s; }
function languageFlag(lang){ return '<img class="lang-flag" src="'+(lang==="id"?FLAG_ID:FLAG_EN)+'" alt="'+(lang==="id"?"Indonesia":"English")+'">'; }
function languagePicker(){ return '<div class="lang-picker" role="group" aria-label="Language"><button type="button" data-lang="en" class="lang-choice '+(UI_LANG==="en"?"on":"")+'" onclick="setLanguage(\'en\',this,event)">'+languageFlag("en")+'<span>EN</span></button><button type="button" data-lang="id" class="lang-choice '+(UI_LANG==="id"?"on":"")+'" onclick="setLanguage(\'id\',this,event)">'+languageFlag("id")+'<span>ID</span></button></div>'; }
function setLanguage(lang,button,e){ if(e){e.preventDefault();e.stopPropagation();} UI_LANG=lang==="id"?"id":"en"; var choices=document.querySelectorAll(".lang-choice"); choices.forEach(function(b){b.classList.toggle("on",b.getAttribute("data-lang")===UI_LANG);b.setAttribute("aria-pressed",b.getAttribute("data-lang")===UI_LANG?"true":"false");}); try{localStorage.setItem("cos.language",UI_LANG);}catch(e){} document.documentElement.lang=UI_LANG; if(document.body.classList.contains("auth")){window.AUTH_LANGUAGE_CHOSEN=true;showLogin();return;} if(typeof PEOPLE!=="undefined"&&PEOPLE&&PEOPLE[ME]){var p=myPrefs();p.language=UI_LANG;saveMyPrefs();} applyShell(); var search=document.getElementById("searchInput"); if(search) search.placeholder=tr("Search everything…"); requestAnimationFrame(function(){document.querySelectorAll(".lang-choice").forEach(function(b){b.classList.toggle("on",b.getAttribute("data-lang")===UI_LANG);b.setAttribute("aria-pressed",b.getAttribute("data-lang")===UI_LANG?"true":"false");});}); /* Switching language used to closePops(), so the menu vanished the instant you
   clicked a flag — an abrupt jump right where the user is still reading. Keep
   the open menu where it is, translate it in place, and re-anchor it in case
   the re-render moved its trigger. */
 var openPop=document.querySelector(".pop.open,.menu.open");
 renderScreen(false); if(S.drawerTask)renderDrawer(); if(typeof wqSurfaces==="function")wqSurfaces(); document.querySelectorAll(".pop,.menu,#sheet,#conn").forEach(localizeVisibleText);
 if(openPop&&openPop.isConnected){
   localizeVisibleText(openPop);
   requestAnimationFrame(function(){
     var anchor=openPop._anchor;
     if(anchor&&anchor.isConnected&&typeof place==="function") place(openPop,anchor);
   });
 } }
function restoreLanguagePreference(){ var p=PEOPLE&&PEOPLE[ME]&&myPrefs(),chosen=!!window.AUTH_LANGUAGE_CHOSEN; if(chosen&&p){p.language=UI_LANG;saveMyPrefs();window.AUTH_LANGUAGE_CHOSEN=false;}else if(p&&p.language)UI_LANG=p.language==="id"?"id":"en"; document.documentElement.lang=UI_LANG; }
function localizeVisibleText(root){ if(UI_LANG!=="id"||!root)return; var w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[],n; while(n=w.nextNode())nodes.push(n); nodes.forEach(function(x){ var raw=x.nodeValue,trim=raw.trim(),translated=UI_ID[trim]; if(translated) x.nodeValue=raw.replace(trim,translated); }); root.querySelectorAll("[placeholder],[title],[aria-label]").forEach(function(el){["placeholder","title","aria-label"].forEach(function(k){var raw=el.getAttribute(k),translated=UI_ID[raw];if(translated)el.setAttribute(k,translated);});}); }

