  ["workflow.taskPanel","workflow",2,"tasks","[data-tour='task-settings']","task-panel-position",["Choose how tasks open for you","Atur cara task terbuka untukmu"],["Task layout is personal to you. Use this gear to choose where Task Detail and New Task open: Right, Center, or Left.","Tata letak task bersifat personal. Gunakan ikon gear ini untuk memilih di mana Task Detail dan New Task terbuka: Kanan, Tengah, atau Kiri."],["Open the gear in the task header, then pick Right, Center or Left.","Buka ikon gear di header task, lalu pilih Kanan, Tengah, atau Kiri."]],
  ["workflow.brief","workflow",3,"tasks","[data-tour='task-brief']","target",["Read the brief before creating","Baca brief sebelum membuat"],["The brief keeps the goal, audience, deliverable, and approval criteria with the task.","Brief menyimpan tujuan, audiens, deliverable, dan kriteria persetujuan bersama task."],["Open the Brief tab in the task drawer.","Buka tab Brief di drawer task."]],
  ["workflow.versions","workflow",3,"tasks","[data-tour='task-versions']","target",["Keep versions with the task","Simpan version bersama task"],["Assets & versions is the single place for uploads, linked Google Drive files, previews, and feedback.","Aset & version adalah satu tempat untuk upload, file Google Drive, pratinjau, dan feedback."],["Open Assets & versions.","Buka Aset & version."]],
  ["workflow.comments","workflow",3,"tasks","[data-tour='task-comments']","target",["Use comments with the right visibility","Gunakan komentar dengan visibilitas yang tepat"],["Comments record decisions. Use the visibility setting for internal discussion or stakeholder-safe updates.","Komentar mencatat keputusan. Gunakan pengaturan visibilitas untuk diskusi internal atau update yang aman untuk stakeholder."],["Open Comments.","Buka Komentar."]],
  ["dependencies.blockedby","dependencies",5,"tasks","[data-tour='task-dependencies']","dependencyDown",["Understand BLOCKED BY","Pahami DIHAMBAT OLEH"],["A downstream task is blocked until the prerequisite is complete. This prevents work from moving ahead without its input.","Task lanjutan terhambat sampai task prasyarat selesai. Ini mencegah pekerjaan berjalan tanpa input yang dibutuhkan."],["See the BLOCKED BY relationship in the practice task.","Lihat relasi DIHAMBAT OLEH di task latihan."]],
  ["dependencies.blocking","dependencies",5,"tasks","[data-tour='task-dependencies']","dependencyUp",["Understand BLOCKING","Pahami MENGHAMBAT"],["The upstream task also shows what it is blocking. Both directions make the dependency chain clear.","Task hulu juga menunjukkan task yang dihambatnya. Kedua arah ini membuat rantai dependensi jelas."],["Open the upstream practice task.","Buka task latihan hulu."]],
  ["workflow.review","workflow",4,"tasks","[data-tour='task-review']","review",["Submit work for review","Kirim pekerjaan untuk ditinjau"],["When your version is ready, submit it to the review stage. A reviewer can approve it or request a revision.","Saat version siap, kirim ke tahap review. Reviewer dapat menyetujui atau meminta revisi."],["See where Submit for review is located.","Lihat lokasi Kirim untuk review."]],
  ["projects.context","projects",8,"tasks","[data-tour='nav-projects']","target",["See the project context","Lihat konteks project"],["Projects connect every task, date, risk, file, and dependency into one delivery picture.","Project menghubungkan setiap task, tanggal, risiko, file, dan dependensi menjadi satu gambaran delivery."],["Open Projects from the navigation.","Buka Project dari navigasi."]],
  ["calendar.schedule","calendar",7,"projects","[data-tour='nav-calendar']","target",["Plan with the calendar","Rencanakan lewat kalender"],["Dates drive workload and deadlines. Dragging a task reschedules it without creating a separate copy.","Tanggal mengatur beban kerja dan tenggat. Menyeret task menjadwalkan ulang tanpa membuat salinan baru."],["Open Calendar from the navigation.","Buka Kalender dari navigasi."]],
  ["resources.assets","resources",4,"calendar","[data-tour='nav-assets']","target",["Find approved assets","Temukan aset yang disetujui"],["Browse assets and preview files before reusing them. Google Drive-linked files stay connected to their task context.","Telusuri aset dan pratinjau file sebelum digunakan lagi. File Google Drive tetap terhubung dengan konteks task-nya."],["Open Assets from the navigation.","Buka Aset dari navigasi."]],
  ["resources.knowledge","resources",4,"assets","#meBtn","knowledge-open",["Open Knowledge from your profile menu","Buka Knowledge dari menu profil"],["Knowledge holds SOPs, guidelines, and working agreements so the team does not need to rely on side conversations.","Knowledge menyimpan SOP, guideline, dan kesepakatan kerja sehingga tim tidak perlu mengandalkan obrolan samping."],["Open Knowledge from the navigation.","Buka Knowledge dari navigasi."]],
  ["messages.open","messages",2,"knowledge","[data-tour='nav-messages']","messages-open",["Open Messages","Buka Messages"],["Messages is the dedicated communication shortcut beside the main navigation. Chat is for quick coordination; task comments stay the work record.","Messages adalah pintasan komunikasi di samping navigasi utama. Chat untuk koordinasi cepat; komentar task tetap menjadi catatan kerja."],["Click Messages in the top bar.","Klik Messages di bar atas."]],
  ["messages.general","messages",2,"messages","[data-tour='messages-general']","target",["Every team has #general","Setiap tim punya #general"],["#general is created automatically for each team and follows team membership — nobody maintains a second roster.","#general dibuat otomatis untuk setiap tim dan mengikuti keanggotaan tim — tidak ada daftar anggota kedua."],["Open a #general channel.","Buka salah satu channel #general."]],
  ["messages.mention","messages",2,"messages","[data-tour='messages-mention']","messages-mention",["Mention a teammate","Sebut rekan tim"],["Type @ and pick a person. The mention goes into your draft only — nothing is sent during the quest.","Ketik @ lalu pilih orang. Mention hanya masuk ke draf — tidak ada yang terkirim selama misi."],["Type @ in the composer and select a person.","Ketik @ di kolom pesan lalu pilih seseorang."]],
  ["messages.attachTask","messages",2,"messages","[data-tour='messages-task-picker']","messages-task-attached",["Attach a task to a message","Lampirkan task ke pesan"],["Task attaches a reference to an existing task — never a copy. It is staged in the composer until you decide to send.","Task melampirkan referensi ke task yang sudah ada — bukan salinan. Ia menunggu di kolom pesan sampai kamu memutuskan untuk mengirim."],["Click Task and pick any task from the list.","Klik Task lalu pilih task mana pun dari daftar."]],
  ["messages.notifications","messages",2,"messages","[data-tour='messages-notifications']","messages-notifications",["Choose how a conversation notifies you","Atur notifikasi percakapan"],["Each conversation can be All messages, Mentions only or Mute. Browser notifications are optional and always need your explicit permission.","Setiap percakapan bisa Semua pesan, Hanya mention, atau Bisukan. Notifikasi browser opsional dan selalu butuh izin eksplisit darimu."],["Change the notification level in the Detail panel.","Ubah tingkat notifikasi di panel Detail."]],
  ["ai.hub","ai",3,"messages","#meBtn","aihub",["Open AI Hub from your profile menu","Buka AI Hub dari menu profil"],["AI Hub is for composing a visual: canvas, layers, safe zones, properties, generation history, and saving to Assets.","AI Hub digunakan untuk menyusun visual: canvas, layer, safe zone, properti, riwayat generate, lalu simpan ke Aset."],["Open your profile menu, then choose AI Hub.","Buka menu profil, lalu pilih AI Hub."]],
  ["ai.intelligence","ai",3,"aihub","[data-tour='ai-intelligence']","target",["Ask AI Intelligence","Gunakan AI Intelligence"],["AI Intelligence helps answer questions and point you to workspace context. It responds in the language used in your question.","AI Intelligence membantu menjawab pertanyaan dan menemukan konteks workspace. Respons mengikuti bahasa pertanyaanmu."],["Open the AI button.","Buka tombol AI."]],
  ["ai.close","ai",2,"aihub","[data-tour='ai-close']","target",["Close the AI panel","Tutup panel AI"],["Close the panel before using search so the next control remains fully visible.","Tutup panel sebelum memakai pencarian agar kontrol berikutnya terlihat sepenuhnya."],["Select the close button in AI Intelligence.","Pilih tombol tutup di AI Intelligence."]],
  ["personal.search","personal",3,"aihub","#searchInput","target",["Search across the workspace","Cari di seluruh workspace"],["Search finds tasks, people, projects, assets, briefs, and knowledge pages from one place.","Pencarian menemukan task, orang, project, aset, brief, dan halaman knowledge dari satu tempat."],["Click inside the search bar beside Notifications.","Klik di dalam kolom pencarian di samping Notifikasi."]],
  ["personal.finish","personal",2,"aihub","#meBtn","target",["Make the workspace yours","Atur workspace sesuai kebutuhanmu"],["Use your profile menu to change language, theme, menu and Home layout. These preferences only affect your account.","Gunakan menu profil untuk mengubah bahasa, tema, menu, dan layout Home. Preferensi ini hanya memengaruhi akunmu."],["Open your profile menu to finish.","Buka menu profil untuk menyelesaikan misi."]]
