function wqL(pair){return UI_LANG==="id"?idTerms(pair[1]):pair[0];}
function wqEligible(){var p=PEOPLE&&PEOPLE[ME];return !!p&&p.perm!=="admin";}
function wqPreview(){return !!(API.on&&SESSION.user&&SESSION.user.perm==="admin"&&SESSION.user.id!==ME);}
function wqDefault(){return {version:2,status:"not_started",path:"member",chapterId:"welcome",stepId:"welcome.intro",xp:0,completedSteps:[],skippedSteps:[],completedChapters:[],startedAt:null,lastSeenAt:null,lastPausedAt:null,lastResumeSource:null,completedAt:null,skippedAt:null,introSeen:false,trainingSessionId:null};}
function wqStoreKey(){return "cos.workspaceQuest.v2."+ME;}
function wqState(){var raw=null,p=myPrefs();try{raw=!API.on?JSON.parse(localStorage.getItem(wqStoreKey())||"null"):(p.workspaceQuest||null);}catch(e){}if(raw&&raw.version===2)return Object.assign(wqDefault(),raw);var s=wqDefault();if(API.on&&p.onboardingDone)s.status="completed",s.xp=100,s.completedSteps=["legacy-tour"];return s;}
function wqSave(s){s.lastSeenAt=new Date().toISOString();if(!API.on){try{localStorage.setItem(wqStoreKey(),JSON.stringify(s));}catch(e){}}else{myPrefs().workspaceQuest=s;saveMyPrefs();}return s;}
function wqStep(id){return WQ_STEPS.filter(function(x){return x[0]===id;})[0]||WQ_STEPS[0];}
function wqChapter(id){return WQ_CHAPTERS.filter(function(x){return x[0]===id;})[0]||WQ_CHAPTERS[0];}
function wqDone(s,id){return s.completedSteps.indexOf(id)>=0||s.skippedSteps.indexOf(id)>=0;}
function wqProgress(s){return Math.min(100,Math.round((s.xp||0)));}
function wqNext(s){return WQ_STEPS.filter(function(x){return !wqDone(s,x[0]);})[0]||null;}
function wqCurrent(s){return wqStep(s.stepId)||wqNext(s)||WQ_STEPS[0];}
