function canShowOnboarding(){var s=wqState();return wqEligible()&&!wqPreview()&&((!API.on&&ME==="sarah")||API.on)&&s.status==="not_started";}
/* §399-402 one personalisation question before the quest starts. Skipping is
   free and leaves the default (Right) in place. */
function showTaskPanelOnboarding(next){
  var pf=myPrefs();
  if(pf.taskPanelPosition||pf.taskPanelAsked||innerWidth<=980) return next();
  window._panelOnboardDone=function(skip){
    var p=myPrefs(); p.taskPanelAsked=true;
    if(skip&&!p.taskPanelPosition) p.taskPanelPosition="right";
    saveMyPrefs(); applyTaskPanelPosition(); closeModal(); next();
  };
  openModal(tr("Choose your task panel"),
    '<p class="hint" style="margin-bottom:14px">'+tr("Choose the layout that feels most comfortable. You can change this anytime in Settings → Layout.")+'</p>'
    + taskPanelPicker(),
    '<button class="btn ghost" onclick="window._panelOnboardDone(true)">'+tr("Skip")+'</button>'
    + '<button class="btn primary" onclick="window._panelOnboardDone(false)">'+tr("Continue")+'</button>');
}
/* v29: one welcome modal on first run. The task-panel position keeps its default (Right)
   and stays changeable in Settings → Layout, instead of a second modal before the quest. */
function showOnboardingIfNeeded(){if(canShowOnboarding())WorkspaceQuest.showWelcome();else wqSurfaces();}
function startOnboarding(manual){if(manual)WorkspaceQuest.replay();else WorkspaceQuest.showWelcome();}
