function notifRows(){ var l=NOTIFS.slice().sort(function(a,b){ return a.ago-b.ago; }); if (!l.length) return emptyBox("No notifications","Assignments, mentions, approvals, requests and deadlines land here.");
  return l.map(function(n){ var tk=task(n.t); var rq=null; var title=tk?tk.title:n.t; var click=tk?'markRead(\''+n.t+'\');openTask(\''+tk.id+'\')':''; if (n.entityType==="message"){ var cv=typeof conv==="function"?conv(n.t):null; title=cv?convTitle(cv):n.t; click='closePops();markRead(\''+attr(n.t)+'\');openConversation(\''+attr(n.t)+'\','+(n.msg?'\''+attr(n.msg)+'\'':'null')+')'; } else if (n.entityType==="gallery"){ click='closePops();markRead(\''+attr(n.t)+'\');go(\'aigallery\')'; } return '<div class="notif'+(n.read?"":" unread")+'" onclick="'+click+'">'+(n.who?av(n.who):'<span class="av" style="background:var(--color-primary)">!</span>')+'<div><div>'+fmt(NTEXT[n.k]||n.k,{who:n.who?first(n.who):"",t:esc(title)})+(n.entityType==="message"&&n.text?'<div class="notif-preview" data-no-translate>'+esc(String(n.text).slice(0,90))+'</div>':'')+'</div><div class="when">'+ago(n.ago)+'</div></div></div>'; }).join(""); }
